    private void btnLoginActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnLoginActionPerformed
        // TODO add your handling code here:
    String username = txtUsername.getText();
    String password = new String(txtPassword.getPassword());

    if (username.isEmpty() || password.isEmpty()) {
        javax.swing.JOptionPane.showMessageDialog(this, "Please enter both username and password.");
        return;
    }

    // 1. Check the database using UserDao
    dao.UserDao userDao = new dao.UserDao();
    model.user loggedInUser = userDao.findByUsername(username);

    // 2. Verify password (Assuming plain text for basic assignment)
    if (loggedInUser != null && loggedInUser.getPasswordHash().equals(password)) {
        
        // 3. Save the user in SessionManager
        util.SessionManager.setCurrentUser(loggedInUser);
        
        // 4. Open Dashboard and close Login
        new view.Dashboard().setVisible(true);
        this.dispose(); // Closes the login window
        
    } else {
        javax.swing.JOptionPane.showMessageDialog(this, "Invalid username or password.", "Error", javax.swing.JOptionPane.ERROR_MESSAGE);
    }    
    }//GEN-LAST:event_btnLoginActionPerformed

